#!/usr/bin/env bash
# hello.sh — print a short greeting.
name=${1:-world}
printf 'Hello, %s\n' "$name"
exit 0

for cmd in curl jq; do
  command -v "$cmd" >/dev/null 2>&1 || { echo "Missing: $cmd" >&2; exit 127; }
done

case "${action:-}" in
  start) echo "Starting" ;;
  stop) echo "Stopping" ;;
  *) echo "Usage: $0 {start|stop}" >&2; exit 2 ;;
esac

while getopts ':f:vn' opt; do
  case "$opt" in
    f) input_file=$OPTARG ;;
    v) verbose=1 ;;
    n) dry_run=1 ;;
    :) printf 'Option -%s needs a value\n' "$OPTARG" >&2; exit 2 ;;
    \?) printf 'Unknown option: -%s\n' "$OPTARG" >&2; exit 2 ;;
  esac
done
shift "$((OPTIND - 1))"

lock_dir="${TMPDIR:-/tmp}/my-script.lock"
mkdir -- "$lock_dir" 2>/dev/null || { echo "Already running" >&2; exit 1; }
trap 'rmdir -- "$lock_dir" 2>/dev/null || true' EXIT
